{"filename": "test_compact_whitespace.py", "content": "import os
import importlib.util

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
compact_whitespace = target.compact_whitespace


def test_strips_leading_and_trailing_whitespace():
    # Spec: "Strip each line" -> leading/trailing whitespace removed.
    assert compact_whitespace(["  hello  "]) == ["hello"]


def test_strips_tabs_and_mixed_whitespace():
    # Whitespace includes tabs; strip removes them at the ends.
    assert compact_whitespace(["\t\tindented\t\t"]) == ["indented"]


def test_omits_whitespace_only_lines():
    # Spec: "Whitespace-only lines should not appear in the output."
    assert compact_whitespace(["   ", "\t", "\n"]) == []


def test_omits_empty_lines():
    # Spec: "omit empty results."
    assert compact_whitespace(["", "a", ""]) == ["a"]


def test_preserves_relative_order():
    # Spec: "The relative order of non-empty stripped lines should be preserved."
    assert compact_whitespace(["  b", "  a", "  c"]) == ["b", "a", "c"]


def test_mixed_content_drops_only_empty():
    assert compact_whitespace(["  hello", "", "  world", "   ", "  foo"]) == ["hello", "world", "foo"]


def test_empty_input_returns_empty_list():
    assert compact_whitespace([]) == []


def test_return_type_is_list():
    assert isinstance(compact_whitespace(["  x"]), list)
    assert isinstance(compact_whitespace([]), list)


def test_internal_single_space_preserved():
    # Strip affects only the ends; a single internal space is unchanged.
    assert compact_whitespace(["  a b  "]) == ["a b"]
"}

