    incoming = {'c': 3}
    assert merge_inventory(base, incoming) == {'a': 1, 'b': 2, 'c': 3}


def test_matching_skus_are_added():
    assert merge_inventory({'a': 5}, {'a': 7}) == {'a': 12}


def test_mixed_matching_and_disjoint():
    assert merge_inventory({'a': 1, 'b': 2}, {'b': 3, 'c': 4}) == {'a': 1, 'b': 5, 'c': 4}


def test_returns_new_dict_object():
    base = {'a': 1}
    incoming = {'b': 2}
    result = merge_inventory(base, incoming)
    assert isinstance(result, dict)
    assert result is not base
    assert result is not incoming


def test_inputs_not_mutated():
    base = {'a': 1, 'b': 2}
